<?php
require_once __DIR__ . '/../config/config.php'; require_once __DIR__ . '/../includes/functions.php'; require_admin();
$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT * FROM courses WHERE id=?');$st->execute([$id]);$course=$st->fetch();if(!$course){http_response_code(404);exit('Course not found.');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($action==='add_lesson'){$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$order=(int)($_POST['sort_order']??0);if($title==='')throw new RuntimeException('Lesson title is required.');$path=upload_file($_FILES['video']??[],'video');$q=$pdo->prepare('INSERT INTO lessons(course_id,title,description,video_path,sort_order) VALUES(?,?,?,?,?)');$q->execute([$id,$title,$desc,$path,$order]);flash('success','Video lesson uploaded successfully.');redirect('admin/course.php?id='.$id);}elseif($action==='update_status'){$status=$_POST['status']??'draft';if(!in_array($status,['draft','published'],true))throw new RuntimeException('Invalid course status.');$q=$pdo->prepare('UPDATE courses SET status=? WHERE id=?');$q->execute([$status,$id]);flash('success','Course publication status updated.');redirect('admin/course.php?id='.$id);}elseif($action==='delete_lesson'){$lid=(int)($_POST['lesson_id']??0);$q=$pdo->prepare('SELECT video_path FROM lessons WHERE id=? AND course_id=?');$q->execute([$lid,$id]);$lesson=$q->fetch();if($lesson){$d=$pdo->prepare('DELETE FROM lessons WHERE id=? AND course_id=?');$d->execute([$lid,$id]);$file=dirname(__DIR__).'/'.$lesson['video_path'];if(is_file($file))unlink($file);}flash('success','Lesson deleted.');redirect('admin/course.php?id='.$id);}}catch(Throwable $e){error_log($e->getMessage());$error=$e->getMessage();}}
$q=$pdo->prepare('SELECT * FROM lessons WHERE course_id=? ORDER BY sort_order,id');$q->execute([$id]);$lessons=$q->fetchAll();page_header('Manage course videos');?><p><a href="<?=e(BASE_URL)?>/admin/dashboard.php">← Back to dashboard</a></p><h1><?=e($course['title'])?></h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><section class="panel"><h2>Course visibility</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update_status"><select name="status"><option value="draft" <?=$course['status']==='draft'?'selected':''?>>Draft</option><option value="published" <?=$course['status']==='published'?'selected':''?>>Published</option></select><button>Save status</button></form></section>
<section class="panel"><h2>Upload a lesson video</h2><p class="muted">Accepted formats: MP4, WebM, OGG. Maximum application limit: 500 MB (also check PHP upload settings).</p><form class="form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_lesson"><label>Lesson title</label><input name="title" maxlength="200" required><label>Lesson description (optional)</label><textarea name="description"></textarea><label>Video file</label><input type="file" name="video" accept="video/mp4,video/webm,video/ogg" required><label>Order</label><input type="number" name="sort_order" value="0"><button>Upload video lesson</button></form></section>
<section class="panel"><h2>Uploaded lessons (<?=count($lessons)?>)</h2><?php foreach($lessons as $l):?><div class="card"><h3><?=e($l['title'])?></h3><p><?=e($l['description'])?></p><video class="video" controls preload="metadata"><source src="<?=e(BASE_URL.'/'.$l['video_path'])?>"></video><form method="post" onsubmit="return confirm('Delete this lesson and its video?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_lesson"><input type="hidden" name="lesson_id" value="<?=(int)$l['id']?>"><button class="btn danger">Delete lesson</button></form></div><?php endforeach;?><?php if(!$lessons):?><p>No video lessons have been uploaded yet.</p><?php endif;?></section><?php page_footer();?>
